function k2Lattice(el,{label='Vo is checking sources',done='Checked sources in'}={}){const cells=[0,1,2,7,null,3,6,5,4],d=108,cyc=Math.round(8*d);
 el.classList.add('k2-ll');el.setAttribute('role','status');el.innerHTML=`<span class="k2-ll-g" aria-hidden="true" style="--cyc:${cyc}ms">${cells.map(c=>`<i${c==null?' class="x"':` style="animation-delay:${c*d}ms"`}></i>`).join('')}</span><span class="k2-ll-t"><span class="k2-ll-l k2-shiny">${label}</span> <span class="k2-ll-s num" aria-hidden="true">0.0s</span></span>`;
 const s=el.querySelector('.k2-ll-s'),t0=performance.now();let raf;const tick=()=>{s.textContent=((performance.now()-t0)/1000).toFixed(1)+'s';raf=requestAnimationFrame(tick)};tick();
 return {done(txt){cancelAnimationFrame(raf);const secs=((performance.now()-t0)/1000).toFixed(1);el.classList.add('is-done');const l=el.querySelector('.k2-ll-l');l.classList.remove('k2-shiny');l.textContent=(txt||done)+' '+secs+'s';s.textContent='';return secs}}}
// ThoughtLine: reasoning-trace header with a live clock. While working, the label breathes (k2-shiny); when it settles (280ms crossfade, 2px blur;
// source 350ms) the steps fold into one line, "Checked 3 sources in 0.6s", and the header becomes a disclosure button that reopens them.
function k2Thought(el,{label='Checking sources…',steps=[],done='Checked {n} sources in'}={}){const id='tl'+Math.random().toString(36).slice(2,7);el.classList.add('k2-tl');
 el.innerHTML=`<button type="button" class="k2-tl-h" aria-expanded="true" aria-controls="${id}" disabled>${I('sparkles','s k2-tl-g')}<span class="k2-tl-say"><span class="k2-tl-w k2-shiny">${label}</span><span class="k2-tl-d"></span></span><span class="k2-tl-c num">0.0s</span>${I('chevron-down','s k2-tl-ch')}</button><div class="k2-tl-b" id="${id}"><ol>${steps.map(s=>`<li>${s}</li>`).join('')}</ol></div>`;
 const h=el.querySelector('.k2-tl-h'),c=el.querySelector('.k2-tl-c'),t0=performance.now();let raf;const tick=()=>{c.textContent=((performance.now()-t0)/1000).toFixed(1)+'s';raf=requestAnimationFrame(tick)};tick();
 h.onclick=()=>{const o=h.getAttribute('aria-expanded')!='true';h.setAttribute('aria-expanded',o);el.classList.toggle('shut',!o)};
 return {settle(){cancelAnimationFrame(raf);const secs=((performance.now()-t0)/1000).toFixed(1);el.querySelector('.k2-tl-d').textContent=done.replace('{n}',steps.length)+' '+secs+'s';c.textContent='';el.classList.add('is-done','shut');h.disabled=false;h.setAttribute('aria-expanded','false')}}}
// SwipeRow: on phones a row swipes left to reveal its actions (snap open past half the drawer or on a 110px/s flick, rubber-band resistance .55
// beyond it, 200ms settle). Button fallback: every row also gets a visible "More" button that opens the same drawer, and focusing an action opens it.
function k2SwipeRow(row,actions){if(!row||row.closest('.k2-swr'))return;const pc=getComputedStyle(row.parentElement);if(pc.display.includes('flex')&&pc.flexDirection.startsWith('row')||pc.overflowX=='auto')return; // never inside a horizontal scroller (fix 3)
 const w=document.createElement('div');w.className='k2-swr';row.before(w);
 const dr=document.createElement('div');dr.className='k2-swr-a';dr.innerHTML=actions;const more=document.createElement('button');more.type='button';more.className='k2-swr-m';more.setAttribute('aria-label','More actions');more.setAttribute('aria-expanded','false');more.innerHTML=I('more','s');
 const fg=document.createElement('div');fg.className='k2-swr-fg';fg.append(row,more);w.append(dr,fg);
 const D=()=>dr.offsetWidth;let x=0,x0=null,y0=0,t0=0,lock=null;const set=(v,anim)=>{x=v;fg.style.transition=anim&&!K2RM()?`transform 200ms ${K2EASE}`:'none';fg.style.transform=v?`translateX(${v}px)`:''};
 const open=o=>{set(o?-D():0,true);w.classList.toggle('open',o);more.setAttribute('aria-expanded',o);dr.querySelectorAll('a,button').forEach(a=>a.tabIndex=o?0:-1)};open(false);
 more.onclick=()=>open(!w.classList.contains('open'));dr.addEventListener('focusin',()=>!w.classList.contains('open')&&open(true));
 fg.addEventListener('pointerdown',e=>{if(e.pointerType=='mouse')return;x0=e.clientX-x;y0=e.clientY;t0=performance.now();lock=null});
 fg.addEventListener('pointermove',e=>{if(x0==null)return;if(lock=='x')w.classList.add('drag');const dx=e.clientX-x0,dy=e.clientY-y0;if(lock==null&&Math.hypot(dx-x,dy)>10)lock=Math.abs(dx-x)>Math.abs(dy)?'x':'y';if(lock!='x')return;fg.setPointerCapture(e.pointerId);const d=D();let v=Math.min(0,dx);if(v<-d)v=-d+(v+d)*.55;set(v,false)});
 const end=e=>{if(x0==null)return;x0=null;w.classList.remove('drag');if(lock!='x')return;const fast=(performance.now()-t0)<250&&x<-30;open(x<-D()/2||fast)};fg.addEventListener('pointerup',end);fg.addEventListener('pointercancel',end);
 fg.addEventListener('click',e=>{if(lock=='x'){e.preventDefault();e.stopPropagation();lock=null}},true);return {open}}
// GradualBlur: a static progressive blur at the bottom edge of a long scrolling page on phones (4 stacked layers, blur 1→8px, each masked to its
// band, as in the source's 'bezier' curve). No motion; it fades out (200ms opacity) at the end of the scroll so the last row is never hidden.
function k2GradualBlur({height=56,bottom=0,layers=4}={}){if(document.querySelector('.k2-gb'))return;
 // fix 3: never cover a composer, the 'who can read' notice or a bottom bar. Skip on pages with a composer; sit above any fixed/sticky bottom bar.
 if(document.querySelector('.compose,.aud,.vocomp,[data-no-gb]'))return;
 [...document.querySelectorAll('body *')].forEach(el=>{const cs=getComputedStyle(el);if((cs.position=='fixed'||cs.position=='sticky')&&cs.display!='none'&&!el.closest('.toasts,.k2-wt')){const r=el.getBoundingClientRect();if(r.height&&r.height<200&&r.bottom>=innerHeight-2&&r.width>innerWidth*.5)bottom=Math.max(bottom,innerHeight-r.top)}});const g=document.createElement('div');g.className='k2-gb';g.setAttribute('aria-hidden','true');g.style.height=height+'px';g.style.bottom=bottom+'px';
 const bz=t=>t*t*(3-2*t);g.innerHTML=[...Array(layers)].map((_,i)=>{const a=i/layers*100,b=(i+1)/layers*100;const bl=(1+bz((i+1)/layers)*7).toFixed(2);const m=`linear-gradient(to bottom,transparent ${a}%,#000 ${b}%)`;return `<i style="backdrop-filter:blur(${bl}px);-webkit-backdrop-filter:blur(${bl}px);mask:${m};-webkit-mask:${m}"></i>`}).join('');document.body.append(g);
 const sc=['.sheet','.main'].map(s=>document.querySelector(s)).find(e=>e&&/auto|scroll/.test(getComputedStyle(e).overflowY))||null;const chk=()=>{const el=sc||document.scrollingElement;g.classList.toggle('end',el.scrollTop+el.clientHeight>=el.scrollHeight-4)};(sc||window).addEventListener('scroll',chk,{passive:true});chk()}
// Auto-wire: grouped tooltips on the Sheet's app tiles and on icon-only buttons; GradualBlur on phones.
document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>{const tl=document.querySelector('.tiles');if(tl){tl.classList.add('k2-wtg');k2Warm('.tiles .tile',{side:'bottom',html:el=>el.querySelector('.tip')?.innerHTML})}
 k2Warm('.mv button[aria-label],.mhead .mi button[aria-label]');if(K2NARROW()&&!document.body.dataset.noGb)k2GradualBlur()},90));

/* Document preview (final pass): any [data-doc] opens the 1200 px specimen render in a dialog. Thumbnails stay at the 600 px render. */
function docPrev(name,title){let d=document.getElementById('docPrev');const B=(window.CV_BASE||'../')+'assets/docs/';
 if(!d){document.body.insertAdjacentHTML('beforeend',`<dialog class="dlg doc-prev" id="docPrev" aria-labelledby="docPrevH"><div class="dh"><h2 id="docPrevH"></h2><button class="x" aria-label="Close" type="button">${I('close','s')}</button></div><div class="db"><img alt="" width="600" height="800" decoding="async"><p class="fp-note">Sample document, fictional. Preview is an inert render; the original file is never altered.</p></div></dialog>`);d=document.getElementById('docPrev');d.querySelector('.x').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close()})}
 d.querySelector('h2').textContent=title||'Preview';const im=d.querySelector('img');im.src=B+name+'-1200.webp';im.alt='Preview: '+(title||name);
 if(typeof openDlg=='function')openDlg('docPrev');else d.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-doc]');if(b){e.preventDefault();docPrev(b.dataset.doc,b.dataset.docT||b.getAttribute('aria-label'))}});
/* DOCT: a document thumbnail (600 px render, 1200 px preview on click) */
const DOCT=(name,title,w=96,cls='')=>`<button type="button" class="doct ${cls}" data-doc="${name}" data-doc-t="${title}" aria-label="Preview ${title}"><img src="${(window.CV_BASE||'../')}assets/docs/${name}-600.webp" alt="" width="${w}" height="${Math.round(w*4/3)}" loading="lazy" decoding="async"><span>${title}</span></button>`;
